#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Khởi tạo LCD qua PCF8574 (Địa chỉ I2C thường là 0x27 hoặc 0x3F, màn hình 16x2)
LiquidCrystal_I2C lcd(0x27, 16, 2); 

#define BTN_K 4 // Chân D4 nối Button K

bool lastBtnState = HIGH;

void setup() {
  // Khởi tạo UART2 trên ESP32 để nối với Arduino (RX2 = GPIO 16, TX2 = GPIO 17)
  // Theo mô tả của bạn: Chân TX(1) và RX(0) của Arduino nối RX2(16) và TX2(17) của ESP32
  Serial2.begin(9600, SERIAL_8N1, 16, 17);

  // Cấu hình nút nhấn với điện trở kéo lên nội bộ
  pinMode(BTN_K, INPUT_PULLUP);

  // Khởi tạo giao tiếp I2C cho LCD (SDA: D21, SCL: D22)
  Wire.begin(21, 22);
  lcd.init();
  lcd.backlight();

  lcd.setCursor(0, 0);
  lcd.print("He thong Quat");
  lcd.setCursor(0, 1);
  lcd.print("Dang ket noi...");
  delay(1500);
  lcd.clear();
}

void loop() {
  // 1. Đọc trạng thái nút bấm K và gửi lệnh sang Arduino
  bool currentBtnState = digitalRead(BTN_K);
  if (currentBtnState != lastBtnState) {
    delay(50); // Chống dội nút nhấn (debounce)
    currentBtnState = digitalRead(BTN_K);
    if (currentBtnState == LOW) {
      // Khi nhấn nút K xuống (nối GND)
      Serial2.println("LED:ON");
    } else {
      // Khi nhả nút K ra
      Serial2.println("LED:OFF");
    }
    lastBtnState = currentBtnState;
  }

  // 2. Nhận dữ liệu nhiệt độ/độ ẩm từ Arduino gửi qua UART2
  if (Serial2.available() > 0) {
    String incomingData = Serial2.readStringUntil('\n');
    incomingData.trim();

    // Phân tích cú pháp chuỗi nhận được dạng: TEMP:25.5,HUM:60.0
    if (incomingData.startsWith("TEMP:")) {
      int commaIndex = incomingData.indexOf(",HUM:");
      if (commaIndex != -1) {
        String tempStr = incomingData.substring(5, commaIndex);
        String humStr = incomingData.substring(commaIndex + 5);

        // Hiển thị lên màn hình LCD qua PCF8574
        lcd.setCursor(0, 0);
        lcd.print("Temp: ");
        lcd.print(tempStr);
        lcd.print(" C   ");

        lcd.setCursor(0, 1);
        lcd.print("Humi: ");
        lcd.print(humStr);
        lcd.print(" %   ");
      }
    }
  }
}
